"""Designer-partial synthesis.

In an ASP.NET *Website Project* the second half of each page's ``partial class``
-- the control field declarations -- is generated by ASP.NET at **runtime**
from the markup.  It never exists on disk.  Without it Roslyn sees thousands of
unresolved identifiers in the code-behind and degrades to error recovery, which
makes every ``find_references`` through the UI layer wrong.

This module generates those partials into ``.index/designer/``.  They are handed
to the Roslyn host as in-memory documents; nothing is ever written into the
workspace.
"""

from __future__ import annotations

import hashlib
import re
from dataclasses import dataclass, field
from pathlib import Path
from typing import Iterable, Optional

from . import fsmap
from .markup import ControlInfo, PageInfo

HEADER = """// <auto-generated>
// Synthesised by dotnet-code-advisor from {markup_rel}.
// ASP.NET generates this partial at runtime for Website Projects; it does not
// exist on disk. Do not edit, do not check in, do not treat as source of truth.
// </auto-generated>
{usings}{open_ns}public partial class {cls}
{{
{fields}
{master}
}}
{close_ns}"""

_IDENT = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")

# C# keywords that cannot be used as a bare field name.  A control whose ID is
# one of these gets an @-escaped declaration rather than being dropped.
CS_KEYWORDS = frozenset(
    """abstract as base bool break byte case catch char checked class const continue
decimal default delegate do double else enum event explicit extern false finally fixed
float for foreach goto if implicit in int interface internal is lock long namespace new
null object operator out override params private protected public readonly ref return
sbyte sealed short sizeof stackalloc static string struct switch this throw true try
typeof uint ulong unchecked unsafe ushort using virtual void volatile while""".split()
)


@dataclass
class SynthResult:
    markup_rel: str
    path: Path
    text: str
    inherits: str
    field_count: int
    skipped_no_id: int = 0
    skipped_duplicate: int = 0
    skipped_collision: int = 0
    skipped_bad_ident: int = 0
    collisions: list[str] = field(default_factory=list)
    emitted_ids: list[str] = field(default_factory=list)
    in_template_fields: int = 0


def synth_path(index_dir: Path, markup_rel: str, inherits: str) -> Path:
    h = hashlib.sha1(markup_rel.encode("utf-8")).hexdigest()[:12]
    safe = re.sub(r"[^A-Za-z0-9_]", "_", inherits)
    return index_dir / "designer" / f"{h}__{safe}.synth.designer.cs"


def has_real_designer(
    markup_file: Path, casemap: Optional[fsmap.CaseMap] = None
) -> Optional[Path]:
    """-- a Web Application Project ships a real ``*.designer.cs``.

    ``foo.aspx`` -> ``foo.aspx.designer.cs``.  When one exists it is authoritative
    and nothing is synthesised for that page.

    The suffix is matched case-insensitively: Visual Studio has emitted both
    ``.designer.cs`` and ``.Designer.cs`` over the years, and missing a real one
    is the expensive direction of the error -- the page would be treated as a
    Website Project and get a synthesised partial on top of the real one, which
    is a duplicate field for every control (CS0102) across the compilation.
    """
    cm = casemap or fsmap.DEFAULT
    cand = cm.resolve_file(markup_file.with_name(markup_file.name + ".designer.cs"))
    if cand is not None:
        return cand
    return cm.resolve_file(markup_file.with_suffix(markup_file.suffix + ".designer.cs"))


def should_synthesise(
    page: PageInfo | None, markup_file: Path, casemap: Optional[fsmap.CaseMap] = None
) -> tuple[bool, Optional[Path]]:
    """Decide per file.  Returns ``(synthesise, real_designer)``."""
    real = has_real_designer(markup_file, casemap)
    if real is not None:
        return False, real
    if page is None or not page.inherits:
        return False, None
    if page.code_attr != "codefile":
        # CodeBehind= is a Web Application Project; MSBuild loads its designer.
        return False, None
    return True, None


def _field_name(ctl_id: str) -> Optional[str]:
    if not _IDENT.match(ctl_id):
        return None
    return f"@{ctl_id}" if ctl_id in CS_KEYWORDS else ctl_id


def emit(
    page: PageInfo,
    markup_rel: str,
    controls: Iterable[ControlInfo],
    codebehind_members: set[str],
    *,
    namespace: Optional[str] = None,
    index_dir: Path,
) -> SynthResult:
    """Build the synthetic partial for one page.

    Over-approximation is deliberate and bounded: controls inside
    ``<ItemTemplate>`` and friends get a field here even though ASP.NET does not
    generate one at runtime, because an unused extra field cannot break the
    compilation -- the CS0102 guard covers the only failure mode -- whereas a
    *missing* field breaks thousands of identifier resolutions.  The count is
    reported so it is never invisible.
    """
    res = SynthResult(
        markup_rel=markup_rel,
        path=synth_path(index_dir, markup_rel, page.inherits or "Page"),
        text="",
        inherits=page.inherits or "Page",
        field_count=0,
    )
    lines: list[str] = []
    seen: set[str] = set()

    for c in controls:
        if not c.ctl_id:
            res.skipped_no_id += 1
            continue
        if c.ctl_id in seen:
            res.skipped_duplicate += 1  # duplicate ID: first wins
            continue
        if c.ctl_id in codebehind_members:
            # CS0102: the type already contains a definition for this name.
            # Emitting it would poison the whole compilation.
            res.skipped_collision += 1
            res.collisions.append(c.ctl_id)
            continue
        fname = _field_name(c.ctl_id)
        if fname is None:
            res.skipped_bad_ident += 1
            continue
        seen.add(c.ctl_id)
        res.emitted_ids.append(c.ctl_id)
        if c.in_template:
            res.in_template_fields += 1
        ctype = c.resolved_type or "System.Web.UI.Control"
        lines.append(
            f"    /// <summary>{c.control_ref} at "
            f"{markup_rel}:{c.line} (resolved via {c.resolution})</summary>\n"
            f"    protected global::{ctype} {fname};"
        )

    master = ""
    if page.master_type:
        master = (
            f"    public new global::{page.master_type} Master\n"
            f"        => (global::{page.master_type})base.Master;"
        )

    open_ns = f"namespace {namespace}\n{{\n" if namespace else ""
    close_ns = "}\n" if namespace else ""

    res.field_count = len(lines)
    res.text = HEADER.format(
        markup_rel=markup_rel,
        cls=page.inherits,
        usings="",
        open_ns=open_ns,
        close_ns=close_ns,
        fields="\n".join(lines),
        master=master,
    )
    return res
